/* The colour for every coverage level, interpolated between bgcolor and dcolor
 * in 5/6/5 steps. Built once per character, so a pixel costs a table lookup
 * rather than a blend. Matches blend565() in tools/screenshot.py. */
static void glyph_palette(uint16 *pal, uint8 levels, uint16 dcolor, uint16 bgcolor)
{
	int fr = (dcolor >> 11) & 0x1f, fg = (dcolor >> 5) & 0x3f, fb = dcolor & 0x1f;
	int br = (bgcolor >> 11) & 0x1f, bg = (bgcolor >> 5) & 0x3f, bb = bgcolor & 0x1f;
	int top = levels - 1;
	int i;

	for(i = 0;i <= top;i++)
	{
		pal[i] = (uint16)(((br + (fr - br) * i / top) << 11)
			| ((bg + (fg - bg) * i / top) << 5)
			| (bb + (fb - bb) * i / top));
	}
}

/* Write one glyph into the window LCD_SetPos() just opened: nbytes bytes, each
 * holding 8/bpp coverage levels, least significant field first. nbytes * 8/bpp
 * has to equal the window's cp*pp, or the panel write desyncs and corrupts the
 * whole screen rather than one character. */
static void blit_glyph(uint8 const *temp, uint16 nbytes, uint8 bpp, uint16 dcolor, uint16 bgcolor)
{
	uint16 pal[GLYPH_MAX_LEVELS];
	uint16 i, j, c;
	uint8 per = (uint8)(8 / bpp);
	uint8 mask = (uint8)((1 << bpp) - 1);

	glyph_palette(pal, (uint8)(1 << bpp), dcolor, bgcolor);

	for(j = 0;j < nbytes;j++)
	{
		for(i = 0;i < per;i++)
		{
			c = pal[(*temp >> (i * bpp)) & mask];
			Write_Data(c >> 8, c);
		}
		temp++;
	}
}

