//==============================================================
//WRITE DATA WORD
void  Write_Data_U16(unsigned int y)
{
	unsigned char m,n;
	m=y>>8;
	n=y;
	Write_Data(m,n);

}
//=============================================================
//WRITE COMMAND

void Write_Cmd(unsigned char CMD)
{ unsigned char i;
 	 
    LCD_CS=0;
	LCD_RS=0;//??????????????
    for(i=0;i<8;i++)
     {  LCD_SCL=0;
        if(CMD&0x80) LCD_SDA=1;
       	else LCD_SDA=0;
       	LCD_SCL=1;
        CMD=CMD<<1;
     }
   	LCD_CS=1;


}

//===============================================================
//WRITE COMMAND PARAMETER 

void  Write_Cmd_Data (unsigned char CMDP)
{ unsigned char i;
 	 
    LCD_CS=0;
   	LCD_RS=1;
    for(i=0;i<8;i++)
     {  LCD_SCL=0;
        if(CMDP&0x80) LCD_SDA=1;
       	else LCD_SDA=0;
       	LCD_SCL=1;
        CMDP=CMDP<<1;
     }
   	LCD_CS=1;

}


//===================================================================
//WRITE DATA CHAR

void Write_Data(unsigned char DH,unsigned char DL)
{unsigned char i;
 	 
    LCD_CS=0;
   	LCD_RS=1;
    for(i=0;i<8;i++)
     {  LCD_SCL=0;
        if(DH&0x80) LCD_SDA=1;
       	else LCD_SDA=0;
       	LCD_SCL=1;
        DH=DH<<1;
     }

    for(i=0;i<8;i++)
     {  LCD_SCL=0;
        if(DL&0x80) LCD_SDA=1;
       	else LCD_SDA=0;
       	LCD_SCL=1;
        DL=DL<<1;
     }

   	LCD_CS=1;

}



