void ILI9341_Initial(void)
{	 
	
 	LCD_CS=1;
	delay_ms(5);
	LCD_RES=0;
	delay_ms(10);
	LCD_RES=1;
	delay_ms(120);

	Write_Cmd(0x11);//exsit sleep mode
	delay_ms(120);

 	Write_Cmd(0xCF);   //power control B
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0xc3); 
	Write_Cmd_Data(0X30); 
      
 	Write_Cmd(0xED); //power on sequence ontrol  
	Write_Cmd_Data(0x64); 
	Write_Cmd_Data(0x03); 
	Write_Cmd_Data(0X12); 
	Write_Cmd_Data(0X81); 
      
 	Write_Cmd(0xE8); //driver timing control A 
	Write_Cmd_Data(0x85); 
	Write_Cmd_Data(0x10); 
	Write_Cmd_Data(0x79); 
      
 	Write_Cmd(0xCB);//power control A   
	Write_Cmd_Data(0x39); 
	Write_Cmd_Data(0x2C); 
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0x34); 
	Write_Cmd_Data(0x02); 
      
 	Write_Cmd(0xF7);//pump ratio control   
	Write_Cmd_Data(0x20); 
      
 	Write_Cmd(0xEA);//driver timing control B   
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0x00); 
      
 	Write_Cmd(0xC0);    //Power control 
	Write_Cmd_Data(0x22);   //VRH[5:0] 
      
 	Write_Cmd(0xC1);    //Power control 
	Write_Cmd_Data(0x11);   //SAP[2:0];BT[3:0] 
      
 	Write_Cmd(0xC5);    //VCM control 
	Write_Cmd_Data(0x3d); 
    //LCD_DataWrite_ILI9341(0x30); 
	Write_Cmd_Data(0x20); 
      
 	Write_Cmd(0xC7);    //VCM control2 
    //LCD_DataWrite_ILI9341(0xBD); 
	Write_Cmd_Data(0xAA); //0xB0 
    
 	Write_Cmd(0x36);    // Memory Access Control 
	Write_Cmd_Data(0xc8); //Row address order//XY exchange and X mirror
      
 	Write_Cmd(0x3A);   //color mode
	Write_Cmd_Data(0x55); 
    
 	Write_Cmd(0xB1); //frame rate control  
	Write_Cmd_Data(0x00);   
	Write_Cmd_Data(0x13); 
      
 	Write_Cmd(0xB6);    // Display Function Control 
	Write_Cmd_Data(0x0A); 
	Write_Cmd_Data(0xA2); 
    
 	Write_Cmd(0xF6); //interface control    
	Write_Cmd_Data(0x01); 
//	Write_Cmd_Data(0x00);//data will be ignore if over the range
	Write_Cmd_Data(0x30); 
      
 	Write_Cmd(0xF2);    // 3Gamma Function Disable 
	Write_Cmd_Data(0x00); 
      
 	Write_Cmd(0x26);    //Gamma curve selected 
	Write_Cmd_Data(0x01); 
      
 	Write_Cmd(0xE0);    //Set Gamma 
	Write_Cmd_Data(0x0F); 
	Write_Cmd_Data(0x3F); 
	Write_Cmd_Data(0x2F); 
	Write_Cmd_Data(0x0C); 
	Write_Cmd_Data(0x10); 
	Write_Cmd_Data(0x0A); 
	Write_Cmd_Data(0x53); 
	Write_Cmd_Data(0XD5); 
	Write_Cmd_Data(0x40); 
	Write_Cmd_Data(0x0A); 
	Write_Cmd_Data(0x13); 
	Write_Cmd_Data(0x03); 
	Write_Cmd_Data(0x08); 
	Write_Cmd_Data(0x03); 
	Write_Cmd_Data(0x00); 
      
 	Write_Cmd(0XE1);    //Set Gamma 
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0x00); 
	Write_Cmd_Data(0x10); 
	Write_Cmd_Data(0x03); 
	Write_Cmd_Data(0x0F); 
	Write_Cmd_Data(0x05); 
	Write_Cmd_Data(0x2C); 
	Write_Cmd_Data(0xA2); 
	Write_Cmd_Data(0x3F); 
	Write_Cmd_Data(0x05); 
	Write_Cmd_Data(0x0E); 
	Write_Cmd_Data(0x0C); 
	Write_Cmd_Data(0x37); 
	Write_Cmd_Data(0x3C); 
	Write_Cmd_Data(0x0F); 
	
//	Write_Cmd(0x33);   //color mode
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
//	Write_Cmd_Data(0x55);
      
 	Write_Cmd(0x11);    //Exit Sleep 
	delay_ms(120);
 	Write_Cmd(0x29);    //Display on 
	delay_ms(50);
}

	   

