//8*12??

void disp_ch(uint8 form, uint16 x, uint16 y,uint8 value,uint16 dcolor,uint16 bgcolor)	
{  
	uint8 const *temp ;//= chlibsmall;  
  uint16 cp = 0;
	uint16 pp = 0;
	uint16 cnum;
	uint8 bpp = 0;
	
	if(form == FORM32X64)
		{
		temp = chlib;
		cp = CHLIB_XDOTS; pp = CHLIB_YDOTS; bpp = CHLIB_BPP;

		if(value == '-')
			temp += 10 * CHLIB_BYTES;	
		else if(value == ' ')
      temp += 11 * CHLIB_BYTES;			
		else if(value >= '0' && value <= '9')
			temp += (value - 48) * CHLIB_BYTES;
		else
			temp += 11 * CHLIB_BYTES;		// not in this table, so show a space
	//	LCD_SetPos(x,x+47,y,y+119);
		}
	else
		{
		temp = chlibsmall;
		cp = CHSMALL_XDOTS; pp = CHSMALL_YDOTS; bpp = CHSMALL_BPP;
		if(value < 32 || value > 126)
			value = ' ';		// labels carry anything; stay inside the table
		temp += (value - 32) * CHSMALL_BYTES;		
		}
//	if(form == FORM32X64)	
		LCD_SetPos(x,x+cp-1,y,y+pp-1);
//	else
//		LCD_SetPos(x,x+14,y,y+pp-1);
	cnum = (uint16)(cp * pp * bpp / 8);
	
  	
	blit_glyph(temp, cnum, bpp, dcolor, bgcolor);
}

void disp_str(uint8 form, uint16 x,uint16 y,uint8 *str,uint16 dcolor,uint16 bgcolor)	  
{  
	unsigned int x1,y1;
	x1=x;
	y1=y;
	while(*str!='\0')
	{	
		
		disp_ch(form,x1,y1,*str,dcolor,bgcolor);
//		if(form == FORM48X120) //big form
//			x1+=47;
//		else			
//			x1+=15;	
			
		if(form == FORM32X64) //big form
			x1+=31;
		else
			x1+=23;	
		str++;
	}	
}

void disp_ch_16_24(uint8 form, uint16 x, uint16 y, uint8 value, uint16 dcolor, uint16 bgcolor)
{
	uint8 const *temp;//= chlibsmall;  
	uint16 cp = 0;
	uint16 pp = 0;
	uint16 cnum;
	uint8 bpp = 0;

	if (form == FORM32X64)
	{
		temp = chlib;
		cp = CHLIB_XDOTS; pp = CHLIB_YDOTS; bpp = CHLIB_BPP;

		if (value == '-')
			temp += 10 * CHLIB_BYTES;
		else if (value == ' ')
			temp += 11 * CHLIB_BYTES;
		else if(value >= '0' && value <= '9')
			temp += (value - 48) * CHLIB_BYTES;
		else
			temp += 11 * CHLIB_BYTES;		// not in this table, so show a space
	}
	else
	{
		temp = char_16_24;
		cp = CH16_XDOTS; pp = CH16_YDOTS; bpp = CH16_BPP;
		if(value < 32 || value > 122)
			value = ' ';		// this table stops at 'z'
		temp += (value - 32) * CH16_BYTES;
	}
	LCD_SetPos(x, x + cp - 1, y, y + pp - 1);
	cnum = (uint16)(cp * pp * bpp / 8);


	blit_glyph(temp, cnum, bpp, dcolor, bgcolor);
}

void disp_str_16_24(uint8 form, uint16 x, uint16 y, uint8 *str, uint16 dcolor, uint16 bgcolor)
{
	unsigned int x1, y1;
	x1 = x;
	y1 = y;
	while (*str != '\0')
	{

		disp_ch_16_24(form, x1, y1, *str, dcolor, bgcolor);
		if (form == FORM32X64) //big form
			x1 += 24;
		else
			x1 += 16;
		str++;
	}
}



/* The row labels use this one. It is the same face and the same cap height as
 * char_16_24, condensed to 12 pixels so that eight characters -- the whole of
 * Str_variable_point.label -- fit between the screen edge and the value box at
 * x=102. Anything outside ASCII is drawn as a space rather than read off the
 * end of the table. */
/* The ten dot face, for the corner readout only.  Same packing and the same
 * range fallback as the twelve dot one; it exists purely because three
 * characters have to fit across thirty dots. */
void disp_ch_10_24(uint16 x, uint16 y, uint8 value, uint16 dcolor, uint16 bgcolor)
{
	uint8 const *temp;

	if(value < 32 || value > 126)
		value = ' ';
	temp = char_10_24 + (value - 32) * CORNER_CH_BYTES;

	LCD_SetPos(x, x + CORNER_CH_XDOTS - 1, y, y + CORNER_CH_YDOTS - 1);
	blit_glyph(temp, CORNER_CH_BYTES, CORNER_CH_BPP, dcolor, bgcolor);
}

void disp_str_10_24(uint16 x, uint16 y, uint8 *str, uint16 dcolor, uint16 bgcolor)
{
	uint16 x1 = x;

	while(*str != 0)
	{
		disp_ch_10_24(x1, y, *str, dcolor, bgcolor);
		x1 += CORNER_CH_XDOTS;
		str++;
	}
}

void disp_ch_12_24(uint16 x, uint16 y, uint8 value, uint16 dcolor, uint16 bgcolor)
{
	uint8 const *temp;
	uint16 cnum;

	if(value < 32 || value > 126)
		value = ' ';
	temp = char_12_24 + (value - 32) * LABEL_CH_BYTES;

	LCD_SetPos(x, x + LABEL_CH_XDOTS - 1, y, y + LABEL_CH_YDOTS - 1);
	cnum = LABEL_CH_BYTES;

	blit_glyph(temp, cnum, LABEL_CH_BPP, dcolor, bgcolor);
}

void disp_str_12_24(uint16 x, uint16 y, uint8 *str, uint16 dcolor, uint16 bgcolor)
{
	uint16 x1 = x;

	while (*str != 0)
	{
		disp_ch_12_24(x1, y, *str, dcolor, bgcolor);
		x1 += LABEL_CH_XDOTS;
		str++;
	}
}

