void disp_icon(uint16 cp, uint16 pp, uint16 const *icon_name, uint16 x,uint16 y,uint16 dcolor, uint16 bgcolor)	
{  
	uint16 j;
	//uint6 const *temp = icon_name;  
	uint16 cnum;

	cnum = pp*cp;
	
  LCD_SetPos(x,x+cp-1,y,y+pp-1);	
	for(j=0;j<cnum;j++)
		{
			Write_Data(icon_name[j]>>8,icon_name[j]);	
		}
}


/* An icon is a 4 bit per pixel index map with its own sixteen entry palette,
 * packed the way the glyphs are: two pixels to a byte, low nibble first,
 * straight across the row boundaries.  Indexed colour costs a quarter of what
 * the literal RGB565 icons cost and still carries sixteen colours, so the row
 * can be as colourful as the screen wants without spending the flash.
 * tools/icongen.py generates both arrays; screenshot.py unpacks them the same
 * way, so a disagreement about the field order shows up as a mangled render. */
void disp_icon4(uint16 cp, uint16 pp, uint8 const *bits, uint16 const *pal, uint16 x, uint16 y)
{
	uint16 n = (uint16)(cp * pp / 2);
	uint16 j, c;

	LCD_SetPos(x, x + cp - 1, y, y + pp - 1);
	for(j = 0;j < n;j++)
	{
		c = pal[bits[j] & 0x0f];
		Write_Data(c >> 8, c);
		c = pal[bits[j] >> 4];
		Write_Data(c >> 8, c);
	}
}
void disp_null_icon(uint16 cp, uint16 pp, uint16 const *icon_name, uint16 x,uint16 y,uint16 dcolor, uint16 bgcolor)	
{  
	uint16 j;
	//uint6 const *temp = icon_name;  
	uint16 cnum;

	cnum = pp*cp;
	
  LCD_SetPos(x,x+cp-1,y,y+pp-1);	
	for(j=0;j<cnum;j++)
		{
			Write_Data(bgcolor>>8,bgcolor);	
		}
}


//Show the in, out and var values where setpoint, fan and sys used to be 
void display_screen_value(uint8 type)
{
	// row n shows VARn, which is what the screen did before it had pages
	display_screen_value_var(type, type - 1);
}

/* The same, but the row and the VAR it shows are chosen separately, so a page
 * past the first can put VAR4 on row 1. */
/* Pick the number of decimal places from what will actually fit.  The box
 * holds VALUE_CHARS cells and a sign and a point each eat one, so any fixed
 * format overruns somewhere: "%.1f" needs five cells for -12.5 and for 123.4
 * alike.  The old code let sprintf write them and then cut at four, leaving a
 * dangling point -- "-12.", "123." -- which reads as a broken number rather
 * than a rounded one.  Rounding can carry into a new digit as well (9.996 at
 * two places is "10.00"), so the result is measured and the places dropped
 * until it fits, ending at a plain rounded integer.
 *
 * A T3-OEM can be set, through Modbus register MODBUS_VALUE_DECIMALS, to drop a
 * fraction that is all zeros ("72.0" and "5.00" become "72" and "5", while
 * "21.5" stays), which is its default, or to show whole numbers only. A
 * setpoint stepped on the unit is always whole, so without this it read "72.0". */
static uint8 value_decimals_mode(void)
{
	if(Modbus.mini_type != MINI_T10P)	/* a Tstat10 is unchanged */
		return VALUE_DECIMALS_AS_FIT;
	return Modbus.value_decimals;
}

static void drop_zero_fraction(uint8 *buf)
{
	uint8 *point = (uint8 *)strchr((char *)buf, '.');
	uint8 *p;

	if(point == NULL)
		return;
	for(p = point + 1;*p != 0;p++)
	{
		if(*p != '0')
			return;
	}
	*point = 0;
	if(strcmp((char *)buf, "-0") == 0)	/* -0.04 rounds to "-0.0" */
		strcpy((char *)buf, "0");
}

static void format_value(uint8 *buf, float v)
{
	int32_t whole;
	int room, digits = 1, places;
	uint8 mode = value_decimals_mode();

	if(v > 9999.0f)
		v = 9999.0f;
	if(v < -999.0f)				/* four cells, one of them the sign */
		v = -999.0f;

	room = VALUE_CHARS - (v < 0 ? 1 : 0);
	whole = (int32_t)(v < 0 ? -v : v);
	while(whole >= 10)
	{
		whole /= 10;
		digits++;
	}

	places = room - digits - 1;		/* the point costs a cell of its own */
	if(mode == VALUE_DECIMALS_WHOLE)
		places = 0;
	for(places = (places > 2) ? 2 : places;places > 0;places--)
	{
		if(places == 2)
			sprintf((char *)buf, "%.2f", v);
		else
			sprintf((char *)buf, "%.1f", v);
		if(strlen((char *)buf) <= VALUE_CHARS)
		{
			if(mode == VALUE_DECIMALS_TRIM)
				drop_zero_fraction(buf);
			return;
		}
	}
	sprintf((char *)buf, "%d", (int)(v < 0 ? v - 0.5f : v + 0.5f));
}

/* The value boxes are VALUE_CHARS cells wide and what lands in them runs from
 * one character to four.  sprintf leaves a terminator part way along, which
 * would stop disp_str() before it repainted the rest of the box and leave the
 * tail of a longer previous value behind, so the full width is squared off with
 * spaces first.  A short value is then pushed right, which keeps the units
 * column of a number in one place as the number grows -- that is the column the
 * eye tracks while a reading changes. */
static void justify_value(uint8 *buf)
{
	uint8 len = 0, pad, i;

	while(len < VALUE_CHARS && buf[len] != 0)
		len++;
	for(i = len;i < VALUE_CHARS;i++)
		buf[i] = 0x20;
	buf[VALUE_CHARS] = 0;

	while(len > 0 && buf[len - 1] == 0x20)
		len--;
	pad = (uint8)(VALUE_CHARS - len);
	if(len == 0 || pad == 0)
		return;
	for(i = VALUE_CHARS;i > 0;i--)
		buf[i - 1] = (i > pad) ? buf[i - 1 - pad] : 0x20;
}

void display_screen_value_var(uint8 type, uint8 var_index)
{
    int i = 0;
    uint8 spbuf[20];
    float show_value = 0;
    uint8 str_length = 0;		
    memset(spbuf, 0x20, VALUE_CHARS);spbuf[VALUE_CHARS] = 0; //Initialise 5 bytes to spaces, so that after showing 12345 a later value of ABC does not come out as ABC45
    if (type >= 1 && type <= 3)  // there are three rows; which VAR each one shows depends on the page
    {// only these three rows support MSV, whichever VARs the page puts on them
			if ((vars[var_index].range >= 101) && (vars[var_index].range <= 103))  // 101 102 103 	MSV range
			{
				//sprintf(spbuf, "%d", msv_data[0][0].msv_value);
				for ( i = 0; i < 8; i++)
				{
					if ((vars[var_index].value/1000) == msv_data[vars[var_index].range - 101][i].msv_value)
					{
							str_length = strlen(msv_data[vars[var_index].range - 101][i].msv_name);
							if (str_length >= VALUE_CHARS)
									str_length = VALUE_CHARS;
							memcpy(spbuf, msv_data[vars[var_index].range - 101][i].msv_name, str_length);
							break;
					}
				}
			}
			else
			{
					show_value = ((float)vars[var_index].value) / 1000;
					if(vars[var_index].value / 1000 >= 10000)
						show_value = 9999;
					
					if(vars[var_index].digital_analog == 0)
					{						
						show_value = vars[var_index].control ? 1 : 0;
						
						switch(vars[var_index].range)
						{
							case OFF_ON:
								if(show_value == 0)			memcpy(spbuf, "OFF ", VALUE_CHARS);
								else							memcpy(spbuf, "ON  ", VALUE_CHARS);
								break;
							case CLOSED_OPEN:					
									if(show_value == 0)			memcpy(spbuf, "CLSD", VALUE_CHARS);
								else							memcpy(spbuf, "OPEN", VALUE_CHARS);
								break;
							case STOP_START:
								if(show_value == 0)					memcpy(spbuf, "STOP", VALUE_CHARS);
								else						memcpy(spbuf, "STRT", VALUE_CHARS);
							break;
							case DISABLED_ENABLED:
								if(show_value == 0)			memcpy(spbuf, "DSBL", VALUE_CHARS);
								else							memcpy(spbuf, "ENBL", VALUE_CHARS);
								break;
							case NORMAL_ALARM:
								if(show_value == 0)			memcpy(spbuf, "NORM", VALUE_CHARS);
								else							memcpy(spbuf, "ALRM", VALUE_CHARS);
								break;
							case NORMAL_HIGH:					
									if(show_value == 0)			memcpy(spbuf, "NORM", VALUE_CHARS);
								else							memcpy(spbuf, "HIGH", VALUE_CHARS);
								break;
							case NORMAL_LOW:
								if(show_value == 0)					memcpy(spbuf, "NORM", VALUE_CHARS);
								else						memcpy(spbuf, "LOW ", VALUE_CHARS);
							break;
							case NO_YES:
								if(show_value == 0)			memcpy(spbuf, "NO  ", VALUE_CHARS);
								else							memcpy(spbuf, "YES ", VALUE_CHARS);
								break;
							case COOL_HEAT:
								if(show_value == 0)			memcpy(spbuf, "COOL", VALUE_CHARS);
								else							memcpy(spbuf, "HEAT", VALUE_CHARS);
								break;
							case UNOCCUPIED_OCCUPIED:					
									if(show_value == 0)			memcpy(spbuf, "UNOC", VALUE_CHARS);
								else							memcpy(spbuf, "OCC ", VALUE_CHARS);
								break;
							case LOW_HIGH:
								if(show_value == 0)					memcpy(spbuf, "LOW ", VALUE_CHARS);
								else						memcpy(spbuf, "HIGH", VALUE_CHARS);
							break;
							case ON_OFF:
								if(show_value == 0)			memcpy(spbuf, "ON  ", VALUE_CHARS);
								else							memcpy(spbuf, "OFF ", VALUE_CHARS);
								break;
							case OPEN_CLOSED:
								if(show_value == 0)			memcpy(spbuf, "OPEN", VALUE_CHARS);
								else							memcpy(spbuf, "CLSD", VALUE_CHARS);
								break;
							case START_STOP:					
									if(show_value == 0)			memcpy(spbuf, "STRT", VALUE_CHARS);
								else							memcpy(spbuf, "STOP", VALUE_CHARS);
								break;
							case ENABLED_DISABLED:
								if(show_value == 0)					memcpy(spbuf, "ENBL", VALUE_CHARS);
								else						memcpy(spbuf, "DSBL", VALUE_CHARS);
							break;
							case ALARM_NORMAL:
								if(show_value == 0)			memcpy(spbuf, "ALRM", VALUE_CHARS);
								else							memcpy(spbuf, "NORM", VALUE_CHARS);
								break;
							case HIGH_NORMAL:
								if(show_value == 0)			memcpy(spbuf, "HIGH", VALUE_CHARS);
								else							memcpy(spbuf, "NORM", VALUE_CHARS);
								break;
							case LOW_NORMAL:					
									if(show_value == 0)			memcpy(spbuf, "LOW ", VALUE_CHARS);
								else							memcpy(spbuf, "NORM", VALUE_CHARS);
								break;
							case YES_NO:
								if(show_value == 0)					memcpy(spbuf, "YES ", VALUE_CHARS);
								else						memcpy(spbuf, "NO  ", VALUE_CHARS);
							break;
							case HEAT_COOL:
								if(show_value == 0)			memcpy(spbuf, "HEAT", VALUE_CHARS);
								else							memcpy(spbuf, "COOL", VALUE_CHARS);
								break;
							case OCCUPIED_UNOCCUPIED:
								if(show_value == 0)					memcpy(spbuf, "OCC ", VALUE_CHARS);
								else						memcpy(spbuf, "UNOC", VALUE_CHARS);
							break;
							case HIGH_LOW:
								if(show_value == 0)			memcpy(spbuf, "HIGH", VALUE_CHARS);
								else							memcpy(spbuf, "LOW ", VALUE_CHARS);
								break;
							default:
								break;
						}						 
					}	
					else
					{
						format_value(spbuf, show_value);
					}
			}
    }
		
		justify_value(spbuf);		// square the box off, then push a short value right

		if(type == 1)	        
			disp_str(FORM15X30, VALUE_XPOS, SETPOINT_POS + VALUE_YOFF, spbuf, SCH_COLOR, TSTAT8_MENU_COLOR2);
    else if (type == 2)
			disp_str(FORM15X30, VALUE_XPOS, FAN_MODE_POS + VALUE_YOFF, spbuf, SCH_COLOR, TSTAT8_MENU_COLOR2);
    else if (type == 3)
      disp_str(FORM15X30, VALUE_XPOS, SYS_MODE_POS + VALUE_YOFF, spbuf, SCH_COLOR, TSTAT8_MENU_COLOR2);
}

