extern uint8 const icon_wall_up[];
extern uint16 const pal_fan_off[];
extern uint16 const pal_fan_on[];
extern uint16 const pal_fan_auto[];
extern uint16 const pal_mode_idle[];
extern uint16 const pal_mode_heat[];
extern uint16 const pal_mode_cool[];
