extern uint16 const pal_mode_cool_ovr[];
extern uint16 const pal_wall_down[];
extern uint16 const pal_wall_up[];

/* Which state an icon shows, from its VAR.  A digital point contributes its
 * control bit and an analogue one the whole part of its value; anything out of
 * range reads as state 0, so an unconfigured panel shows fan off, idle and
 * walls down rather than indexing past the table. */
static uint8 icon_state(uint8 index, uint8 count)
{
	int32_t v;

	if(index >= MAX_VARS)
		return 0;
	if(vars[index].digital_analog == 0)
		v = vars[index].control ? 1 : 0;
	else
		v = vars[index].value / 1000;
	if(v < 0 || v >= (int32_t)count)
		return 0;
	return (uint8)v;
}

/* The three icons: what the circulation fans are doing, what the room is
 * calling for, and where the greenhouse sidewalls are.  See the ICON3_* block
 * in LCD_TSTAT.h for the VAR each one reads and the state encoding. */
void display_icon(void)
{
	static uint8 const *const fan_bits[ICON3_FAN_STATES] = { icon_fan_off, icon_fan_on, icon_fan_auto };
	static uint16 const *const fan_pal[ICON3_FAN_STATES] = { pal_fan_off, pal_fan_on, pal_fan_auto };
	static uint8 const *const mode_bits[ICON3_MODE_STATES] = { icon_mode_idle, icon_mode_heat, icon_mode_cool, icon_mode_heat_ovr, icon_mode_cool_ovr };
	static uint16 const *const mode_pal[ICON3_MODE_STATES] = { pal_mode_idle, pal_mode_heat, pal_mode_cool, pal_mode_heat_ovr, pal_mode_cool_ovr };
	static uint8 const *const wall_bits[ICON3_WALL_STATES] = { icon_wall_down, icon_wall_up };
	static uint16 const *const wall_pal[ICON3_WALL_STATES] = { pal_wall_down, pal_wall_up };
	uint8 n;

	n = icon_state(ICON3_FAN_VAR, ICON3_FAN_STATES);
	disp_icon4(ICON3_XDOTS, ICON3_YDOTS, fan_bits[n], fan_pal[n], ICON3_FAN_POS, ICON_POS);
	n = icon_state(ICON3_MODE_VAR, ICON3_MODE_STATES);
	disp_icon4(ICON3_XDOTS, ICON3_YDOTS, mode_bits[n], mode_pal[n], ICON3_MODE_POS, ICON_POS);
	n = icon_state(ICON3_WALL_VAR, ICON3_WALL_STATES);
	disp_icon4(ICON3_XDOTS, ICON3_YDOTS, wall_bits[n], wall_pal[n], ICON3_WALL_POS, ICON_POS);
}

/* A column of marks in the top right corner, one per page, the current one
 * bright and the rest dim.  disp_null_icon() fills a rectangle, so this needs
 * no bitmap and no font.  The whole strip is wiped first so that dropping a
 * page cannot leave its mark behind, and a panel with one page gets nothing. */
void display_page_marks(uint8 current, uint8 count)
{
	uint8 i;

	disp_null_icon(PAGE_MARK_XDOTS, PAGE_MARK_STRIP_YDOTS, 0,
		PAGE_MARK_XPOS, PAGE_MARK_YPOS, TSTAT8_BACK_COLOR, TSTAT8_BACK_COLOR);
	if(count < 2)
		return;
	if(count > PAGE_MARK_MAX)		/* the strip is only this tall */
		count = PAGE_MARK_MAX;

	for(i = 0;i < count;i++)
		disp_null_icon(PAGE_MARK_XDOTS, PAGE_MARK_YDOTS, 0,
			PAGE_MARK_XPOS, PAGE_MARK_YPOS + i * PAGE_MARK_PITCH,
			TSTAT8_BACK_COLOR, (i == current) ? SCH_COLOR : PAGE_MARK_DIM_COLOR);
}

/* The corner humidity readout, page 1 only.  See the RH_* block in
 * LCD_TSTAT.h for the VAR it reads and why the percent sign is on its own
 * line.  Out of range reads as blank rather than as a wrong number. */
void display_top_rh(uint8 page)
{
	uint8 buf[RH_CHARS + 1];
	int32_t v;

	if(page != 0)
	{
		disp_null_icon(RH_XDOTS, RH_YDOTS, 0, RH_XPOS, RH_LABEL_YPOS,
			TSTAT8_BACK_COLOR, TSTAT8_BACK_COLOR);
		return;
	}

	v = (TOP_RH_VAR < MAX_VARS) ? vars[TOP_RH_VAR].value / 1000 : -1;
	if(v < 0 || v > 99)				/* out of range shows blank, not a wrong number */
		v = -1;

	buf[0] = (uint8)(v >= 10 ? 0x30 + v / 10 : 0x20);
	buf[1] = (uint8)(v >= 0 ? 0x30 + v % 10 : 0x20);
	buf[2] = (uint8)(v >= 0 ? '%' : 0x20);
	buf[3] = 0;
	disp_str_10_24(RH_LABEL_XPOS, RH_LABEL_YPOS, (uint8 *)"RH", SCH_COLOR, TSTAT8_BACK_COLOR);
	disp_str_10_24(RH_XPOS, RH_YPOS, buf, SCH_COLOR, TSTAT8_BACK_COLOR);
}
/* "Sep 20 | 12:00 PM" in the 12 dot face. Seventeen characters fit across the
 * screen, where the face the clock used before could only manage ten. */
void display_clock(void)
{
	static char const month[12][4] = {"Jan","Feb","Mar","Apr","May","Jun",
									"Jul","Aug","Sep","Oct","Nov","Dec"};
	char buf[CLOCK_CHARS + 1];
	uint8 mon = Rtc.Clk.mon;
	uint8 h12 = (uint8)(Rtc.Clk.hour % 12);
	uint8 pm = (uint8)(Rtc.Clk.hour >= 12);

	if(mon < 1 || mon > 12)
		mon = 1;
	if(h12 == 0)
		h12 = 12;

	buf[0] = month[mon - 1][0];
	buf[1] = month[mon - 1][1];
	buf[2] = month[mon - 1][2];
	buf[3] = ' ';
	buf[4] = (char)(Rtc.Clk.day / 10 + '0');
	buf[5] = (char)(Rtc.Clk.day % 10 + '0');
	buf[6] = ' ';
	buf[7] = '|';
	buf[8] = ' ';
	buf[9] = h12 >= 10 ? '1' : ' ';
	buf[10] = (char)(h12 % 10 + '0');
	buf[11] = ':';
	buf[12] = (char)(Rtc.Clk.min / 10 + '0');
	buf[13] = (char)(Rtc.Clk.min % 10 + '0');
	buf[14] = ' ';
	buf[15] = pm ? 'P' : 'A';
	buf[16] = 'M';
	buf[17] = 0;

	disp_str_12_24(CLOCK_XPOS, TIME_POS + CLOCK_YOFF, (uint8 *)buf,
		TSTAT8_CH_COLOR, TSTAT8_MENU_COLOR2);
}

