int16 mul_analog_input[10];
uint8  disp_item_queue[15];
extern uint16_t count_show_mstp_err;
//uint8 Disp_AI1[];
void Refresh_scroll(void)
{
	uint8 i,j;
	uint8 mode;
	memset(&scroll_ram[0][0],0,MAX_SCOROLL);
	//if(lcd_rotate_max > 9)
		lcd_rotate_max = 1;
	//lcd_rotate_index = 0;
	if(lcd_rotate_max > 0)
	{
		if((Modbus.com_config[0] == BACNET_SLAVE || Modbus.com_config[0] == BACNET_MASTER) && \
			(flag_mstp_err[0] == 1) && (count_show_mstp_err++ < 20) && (com_rx[0] > 100))
		{			
			memcpy(&scroll_ram[0][0],"Baud error      ",MAX_SCOROLL);
		}
		else if(SSID_Info.IP_Wifi_Status <= 1)
		{
			j = 0;
			scroll_ram[0][j++] = '2';
			scroll_ram[0][j++] = '0';
			scroll_ram[0][j++] =  Rtc.Clk.year / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.year % 10 + '0';
			scroll_ram[0][j++] = '-';
			scroll_ram[0][j++] =  Rtc.Clk.mon / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.mon % 10 + '0';
			scroll_ram[0][j++] = '-';
			scroll_ram[0][j++] =  Rtc.Clk.day / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.day % 10 + '0';
			scroll_ram[0][j++] = ' ';
			scroll_ram[0][j++] =  Rtc.Clk.hour / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.hour % 10 + '0';
			scroll_ram[0][j++] = ':';
			scroll_ram[0][j++] =  Rtc.Clk.min / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.min % 10 + '0';
			scroll_ram[0][j++] = ':';
			scroll_ram[0][j++] =  Rtc.Clk.sec / 10 + '0';
			scroll_ram[0][j++] =  Rtc.Clk.sec % 10 + '0';
			scroll_ram[0][j++] = ' ';
//			if(Daylight_Saving_Time)  // timezone : +8 ---> 800
//			{
//				if((Rtc.Clk.day_of_year >= 105) && (Rtc.Clk.day_of_year <= 260))
//				{
//					if(Rtc.Clk.hour < 23)
//					{
//						scroll_ram[0][j++] =  (Rtc.Clk.hour + 1) / 10 + '0';
//						scroll_ram[0][j++] =  (Rtc.Clk.hour + 1) % 10 + '0';
//					}
//					else
//					{
//						scroll_ram[0][j++] =  '0';
//						scroll_ram[0][j++] =  '0';
//					}
//				}
//					
//			}
		}
		else if(SSID_Info.IP_Wifi_Status == 2)
		{			
			sprintf(&scroll_ram[0][0],"%d.%d.%d.%d ",(uint8)SSID_Info.ip_addr[0],(uint8)SSID_Info.ip_addr[1],(uint8)SSID_Info.ip_addr[2], (uint8)SSID_Info.ip_addr[3]);
		}
		else if(SSID_Info.IP_Wifi_Status == 3)
		{
			memcpy(&scroll_ram[0][0],"wifi connected ",MAX_SCOROLL);
		}	
		else if(SSID_Info.IP_Wifi_Status == 4)
		{
			memcpy(&scroll_ram[0][0],"wifi disconnct ",MAX_SCOROLL);
		}		
		else if(SSID_Info.IP_Wifi_Status == 5)
		{
			memcpy(&scroll_ram[0][0],"wifi configure ",MAX_SCOROLL);
		}
	}

}

void display_scroll(void)
{
	uint8 cnt;
	uint8 i;
	
	//if(lcd_rotate_index == 0)
	{	
		Refresh_scroll();
	
		
	lcd_rotate_max = 1;
	if(lcd_rotate_max == 0)
	{
		for(i=0;i<10;i++)
			scroll_buf[i] = scroll_ram[lcd_rotate_max-1][i];
		scroll_buf[10] = '\0'; 
		disp_str(FORM15X30, 0,TIME_POS,scroll_buf,TSTAT8_CH_COLOR,TSTAT8_MENU_COLOR2); 
	}
	
	if(lcd_rotate_max > 0)
	{
		if(scroll >= &scroll_ram[lcd_rotate_max-1][1])
		{
			for(i=0;i<(&scroll_ram[lcd_rotate_max-1][MAX_SCOROLL - 1] - scroll + 1);i++)
				scroll_buf[i] = *(scroll+i);
			for(i=0;i<(scroll + MAX_SCOROLL - 1 - &scroll_ram[lcd_rotate_max-1][MAX_SCOROLL - 1]);i++)
				scroll_buf[&scroll_ram[lcd_rotate_max-1][MAX_SCOROLL- 1] - scroll + 1 + i] = scroll_ram[0][i];
		}
		else
		{
			for(i=0;i<10;i++)
				scroll_buf[i] = *(scroll+i);
		}
		if(scroll == &scroll_ram[lcd_rotate_max-1][MAX_SCOROLL - 1])
			scroll = &scroll_ram[0][0];	
		else	
			scroll++;
		
		scroll_buf[10] = '\0'; 
		disp_str(FORM15X30, 30,TIME_POS,scroll_buf,TSTAT8_CH_COLOR,TSTAT8_MENU_COLOR2); 
	}
}

	
}

uint8 const WRN_INFO[30] = {"Reverse AC supply is detected "}; 
uint8 const WRN_INFO_BACNET[30] = {"BACNET MSTP is detected "}; 
void scroll_warning(uint8 item)
{
	uint8 scroll_buf[11];
	uint8 i,j;
	static uint8 cnt = 0;
 
	disp_null_icon(239, 30, 0, 0,TIME_POS,0xf800, TSTAT8_MENU_COLOR2);
	for(i=0;i<10;i++)
	{
	 if(item == 0)	
		scroll_buf[i] = WRN_INFO[i + cnt];
	 else if(item == 1)
		scroll_buf[i] = WRN_INFO_BACNET[i + cnt];
	}
	scroll_buf[10] = '\0';
	disp_str(FORM15X30,30,TIME_POS,scroll_buf,0xf800,TSTAT8_MENU_COLOR2); 
  
	if(cnt < 25)
		cnt++;
	else
		cnt = 0;
	
}


/* Blank the rectangle x0..x1-1, y0..y1-1, clipped to the unit band. */
static void unit_band_rect(int16 x0, int16 y0, int16 x1, int16 y1)
{
	if(x0 < UNIT_BAND_XPOS)
		x0 = UNIT_BAND_XPOS;
	if(x1 > UNIT_BAND_XPOS + UNIT_BAND_XDOTS)
		x1 = UNIT_BAND_XPOS + UNIT_BAND_XDOTS;
	if(y0 < UNIT_BAND_YPOS)
		y0 = UNIT_BAND_YPOS;
	if(y1 > UNIT_BAND_YPOS + UNIT_BAND_YDOTS)
		y1 = UNIT_BAND_YPOS + UNIT_BAND_YDOTS;
	if(x1 > x0 && y1 > y0)
		disp_null_icon((uint16)(x1 - x0), (uint16)(y1 - y0), 0, (uint16)x0, (uint16)y0,
			TSTAT8_BACK_COLOR, TSTAT8_BACK_COLOR);
}

/* Blank whatever part of the unit band a unit has left bare. The unit is an
 * optional ring (rw 0 for none) at rx, ry, rw x rh, then chars small glyphs
 * from tx on the UNIT_TEXT_YPOS line; chars 0 blanks the whole band. */
static void unit_band_blank(int16 rx, int16 ry, int16 rw, int16 rh, int16 tx, uint8 chars)
{
	int16 bx0 = UNIT_BAND_XPOS, bx1 = UNIT_BAND_XPOS + UNIT_BAND_XDOTS;
	int16 by0 = UNIT_BAND_YPOS, by1 = UNIT_BAND_YPOS + UNIT_BAND_YDOTS;
	int16 tx1 = chars ? (int16)(tx + (chars - 1) * 23 + CHSMALL_XDOTS) : tx;	/* disp_str advances 23 */

	if(chars == 0)
		tx = tx1 = bx1;
	unit_band_rect(bx0, by0, rw ? rx : tx, by1);			// left of everything
	if(rw)
	{
		unit_band_rect(rx, by0, rx + rw, ry);				// above the ring
		unit_band_rect(rx, ry + rh, rx + rw, by1);			// below it
		unit_band_rect(rx + rw, by0, tx, by1);				// between ring and text
	}
	if(chars)
	{
		unit_band_rect(tx, by0, tx1, UNIT_TEXT_YPOS);						// above the text
		unit_band_rect(tx, UNIT_TEXT_YPOS + CHSMALL_YDOTS, tx1, by1);		// below it
	}
	unit_band_rect(tx1, by0, bx1, by1);						// right of everything
}

void Top_area_display(uint8 item, int16 value, uint8 unit)
{
	int16 value_buf;
	switch(item)
	{
	case TOP_AREA_DISP_ITEM_TEMPERATURE:
		/* Whole numbers only, three digits at most. Temperature and humidity
		 * arrive in tenths and are rounded to units; the other units already
		 * come through whole. The value is right aligned across the three
		 * cells with leading zeros blanked, and no decimal point is drawn. */
		{
			uint8 tenths = (unit == TOP_AREA_DISP_UNIT_C || unit == TOP_AREA_DISP_UNIT_F
					|| unit == TOP_AREA_DISP_UNIT_RH);
			uint8 neg = 0;
			uint8 cells[3];

			value_buf = value;
			if(value_buf < 0)
			{
				neg = 1;
				value_buf = -value_buf;
			}
			if(tenths)
				value_buf = (int16)((value_buf + 5) / 10);
			if(value_buf > 999)
				value_buf = 999;

			/* The sign rides in the cell left of the first digit rather than in a
			 * column of its own: the number starts at x=30 now and the RS485
			 * arrows own everything to the left of it.  A three digit negative has
			 * no cell to put the sign in, so the magnitude is capped at two. */
			if(neg && value_buf > 99)
				value_buf = 99;

			cells[0] = cells[1] = ' ';
			cells[2] = (uint8)(0x30 + value_buf % 10);
			if(value_buf >= 10)
				cells[1] = (uint8)(0x30 + (value_buf / 10) % 10);
			if(value_buf >= 100)
				cells[0] = (uint8)(0x30 + value_buf / 100);
			if(neg)
				cells[value_buf < 10 ? 1 : 0] = '-';

			disp_ch(0, FIRST_CH_POS, THERM_METER_POS, cells[0], TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
			disp_ch(0, SECOND_CH_POS, THERM_METER_POS, cells[1], TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
			disp_ch(0, THIRD_CH_POS, THERM_METER_POS, cells[2], TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
		}
		break;
	default:
	break; 
	
	}

	
//	if(icon.unit == 1)
//	{
//		if(EEP_DEGCorF == 0)

	/* A one character unit hangs off UNIT_POS with the degree ring to its left
	 * where the temperature scales want one.  A two character unit starts at
	 * UNIT2_POS instead: two 23 dot advances back from UNIT_POS would begin at
	 * x=166, inside the third digit cell, which put "%R" on the hundreds digit.
	 *
	 * The band any unit can reach is then blanked only where the unit just drawn
	 * does not reach, so that switching from a two character unit to a one
	 * character one cannot leave its tail on screen.  Blanking the whole band
	 * first and drawing over it made the unit blink on every refresh, since the
	 * band sat empty until the glyphs went back; a glyph cell repaints its own
	 * background, so drawing straight over the old unit never shows a gap. */
	switch(unit)
	{
	case TOP_AREA_DISP_UNIT_C:
	case TOP_AREA_DISP_UNIT_F:
		disp_icon(14, 14, degree_o, UNIT_POS - 14, UNIT_YPOS, TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
		disp_str(FORM15X30, UNIT_POS, UNIT_TEXT_YPOS, (uint8 *)(unit == TOP_AREA_DISP_UNIT_C ? "C" : "F"),
			TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
		unit_band_blank(UNIT_POS - 14, UNIT_YPOS, 14, 14, UNIT_POS, 1);
		break;
	case TOP_AREA_DISP_UNIT_PERCENT:
		disp_str(FORM15X30, UNIT_POS, UNIT_TEXT_YPOS, "%", TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
		unit_band_blank(0, 0, 0, 0, UNIT_POS, 1);
		break;
	case TOP_AREA_DISP_UNIT_RH:
	case TOP_AREA_DISP_UNIT_PPM:
	case TOP_AREA_DISP_UNIT_kPa:
	case TOP_AREA_DISP_UNIT_Pa:
		disp_str(FORM15X30, UNIT2_POS, UNIT_TEXT_YPOS,
			(uint8 *)(unit == TOP_AREA_DISP_UNIT_RH ? "%R" : unit == TOP_AREA_DISP_UNIT_PPM ? "pp"
				: unit == TOP_AREA_DISP_UNIT_kPa ? "kP" : "Pa"),
			TSTAT8_CH_COLOR, TSTAT8_BACK_COLOR);
		unit_band_blank(0, 0, 0, 0, UNIT2_POS, 2);
		break;
	default:					/* TOP_AREA_DISP_UNIT_NONE, and anything unknown */
		unit_band_blank(0, 0, 0, 0, 0, 0);
		break;
	}
}


